/* ------------------------------------------------------------------------------
@name: Header
@description: Header
--------------------------------------------------------------------------------- */
import Scrolllable from "@utilities/Scrolllable";

const Header = (() => {
  // - handleClick
  const handleClick = () => {
    if ($(window).width() >= 991.98) {
      $(".header__menu").on("click", (e) => {
        if (e.target === e.currentTarget) {
          handleClose();
        }
      });
    }
  };

  // - handleEsc
  const handleEsc = () => {
    $(document).on("keyup", (e) => {
      if (e.which === 27) {
        handleClose();
      }
    });
  };

  // - handleClose
  const handleClose = () => {
    if ($("body").hasClass("show-menu")) {
      $("body").removeClass("show-menu");
      Scrolllable.enable();
    }
  };

  // - setVhUnit
  const setVhUnit = () => {
    var vh = $(window).height() * 0.01;
    $(":root").css("--vh", vh + "px");
  };

  const handleTheme = () => {
    const $html = $("html");

    const setTheme = (theme) => {
      $html.removeClass("theme-light theme-dark").addClass(`theme-${theme}`);
      localStorage.setItem("current-theme", theme);
    };

    setTheme(
      localStorage.getItem("current-theme") === "dark" ? "dark" : "light",
    );

    $(".js-theme-dark").on("click", () => setTheme("dark"));
    $(".js-theme-light").on("click", () => setTheme("light"));

    requestAnimationFrame(() => {
      requestAnimationFrame(() => $html.addClass("theme-ready"));
    });
  };

  // - init
  const init = () => {
    handleClick();
    handleEsc();
    setVhUnit();
    handleTheme();
  };

  return {
    init,
  };
})();

export default Header;
