/* ------------------------------------------------------------------------------
@name: Projects
@description: Projects
--------------------------------------------------------------------------------- */

import WindowResize from "@utilities/WindowResize.js";

const Projects = (() => {
  const BREAKPOINT_DESKTOP = 991.98;

  let _isMobileState = null;

  // - isMobile
  const isMobile = () => $(window).width() <= BREAKPOINT_DESKTOP;

  // - handleDescription
  const handleDescription = () => {
    $(".projects .projects__desc").each((index, el) => {
      const $desc = $(el);
      const $readMore = $desc.next(".js-more");

      const isOverflowing = $desc[0].scrollHeight > $desc[0].clientHeight;

      if (isOverflowing) {
        $readMore.addClass("show");
      }
    });

    $(".projects .js-more").on("click.projects", (e) => {
      const $readMore = $(e.currentTarget);
      const $desc = $readMore.prev(".projects__desc");
      $desc.toggleClass("expanded");
      $readMore.text($desc.hasClass("expanded") ? "Read Less" : "Read More");
    });
  };

  // - handleSet
  const handleSet = () => {
    $(".projects__panel").each((index, panel) => {
      $(panel)
        .find(".projects__item")
        .eq(0)
        .addClass("projects__item--active")
        .find(".projects__wrap")
        .show();
    });
  };

  // - handleClick
  const handleClick = () => {
    $(".projects__item").on("click.projects", (e) => {
      const _this = $(e.currentTarget);
      _this
        .toggleClass("projects__item--active")
        .find(".projects__wrap")
        .slideToggle();
      // _this
      //   .siblings(".projects__item")
      //   .removeClass("projects__item--active")
      //   .find(".projects__wrap")
      //   .slideUp();
    });
  };

  // - handleClickButton
  const handleClickButton = () => {
    $(".projects__link .btn.btn--secondary").on("click.projects", (e) => {
      e.stopPropagation();
    });
  };

  // - handleDestroy
  const handleDestroy = () => {
    const mobile = isMobile();

    if (mobile === _isMobileState) return;
    _isMobileState = mobile;

    $(".projects__item").off("click.projects");
    $(".projects .js-more").off("click.projects");
    $(".projects__link .btn.btn--secondary").off("click.projects");

    if (mobile) {
      $(".projects__item")
        .removeClass("projects__item--active")
        .find(".projects__wrap")
        .hide();
      handleSet();
      handleClick();
      handleClickButton();
    } else {
      handleDescription();
    }
  };

  // - init
  const init = () => {
    handleDestroy();
    WindowResize.resize(handleDestroy);
  };

  return {
    init,
  };
})();

export default Projects;
